{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 AS WITH ranked_data AS ( SELECT \"Channel Name\" AS MARKETPLACE, CASE WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%CRED%\' THEN \'CRED\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%MYNTRA%\' THEN \'MYNTRA\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%AJIO%\' THEN \'AJIO\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%STORE%\' THEN \'STORE\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%AMAZON%\' THEN \'AMAZON\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%DONOSHOP%\' THEN \'POPCLUB\' ELSE \"Channel Name\" END AS MARKETPLACE_MAPPED, \"Display Order Code\" AS order_name, CASE WHEN marketplace_mapped = \'SHOPIFY\' THEN SUBSTRING(\"Sale Order Code\", 2, LENGTH(\"Sale Order Code\") - 1) ELSE \"Sale Order Code\" END AS order_id, \"Notification Email\" AS EMAIL, \"Notification Mobile\" AS PHONE, \"Shipping Address Phone\" AS SHIPPING_ADDRESS_PHONE, \"Shipping Address Name\" AS NAME, \"Fulfillment TAT\" AS FULFILLMENT_TAT, NULLIF(CREATED, \'\')::TIMESTAMP AS UC_CREATED, NULLIF(UPDATED, \'\')::DATE AS SHIPPING_LAST_UPDATE_DATE, NULLIF(UPDATED, \'\')::TIMESTAMP AS SHIPPING_LAST_UPDATE_TIMESTAMP, \"Item SKU Code\" AS SKU, LEFT(\"Item SKU Code\", LENGTH(\"Item SKU Code\") - CHARINDEX(\'-\', REVERSE(\"Item SKU Code\"))) AS SKU_GROUP, \"Channel Product Id\" AS PRODUCT_ID, \"Item Type Name\" AS PRODUCT_NAME, CASE WHEN \"Sale Order Item Status\" LIKE \'PICKING_%\' THEN \"Shipping Package Status Code\" ELSE \"Sale Order Item Status\" END AS SALE_ORDER_ITEM_STATUS, \"Item Details\" AS ITEM_DETAILS, \"Shipping Address Line 1\" AS ADDRESS_LINE_1, \"Shipping Address Line 2\" AS ADDRESS_LINE_2, \"Shipping Address City\" AS CITY, \"Shipping Address State\" AS STATE, \"Shipping Address Country\" AS COUNTRY, \"Shipping Address Pincode\" AS PINCODE, \"Sale Order Status\" AS ORDER_STATUS, NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\')::DATE AS ORDER_DATE, NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\')::TIMESTAMP AS ORDER_TIMESTAMP, NULLIF(\"Shipping Package Creation Date\", \'\')::TIMESTAMP AS SHIPPING_PACKAGE_CREATED, \'1\' AS SUBORDER_QUANTITY, discount AS DISCOUNT, \"Tax Value\" AS TAX, \"Selling Price\" AS SELLING_PRICE, \"Shipping Package Code\" AS SHIPPINGPACKAGECODE, \"Shipping Package Status Code\" AS SHIPPINGPACKAGESTATUS, facility AS WAREHOUSE_NAME, CASE WHEN marketplace_mapped = \'SHOPIFY\' THEN SUBSTRING(\"Sale Order Item Code\", 2, LENGTH(\"Sale Order Item Code\") - 1) ELSE \"Sale Order Item Code\" END AS SALEORDERITEMCODE, mrp AS MRP, \"Shipping provider\" AS COURIER, \"Shipping Tracking Status\" AS SHIPPING_STATUS, NULLIF(\"Shipping Package Creation Date\", \'\')::DATE AS CREATED_TIMESTAMP, NULLIF(\"Packing Time\", \'\')::DATE AS PACKED_TIMESTAMP, NULLIF(\"Dispatch Date\", \'\')::DATE AS DISPATCH_DATE, NULLIF(\"Dispatch Date\", \'\')::TIMESTAMP AS DISPATCHED_TIMESTAMP, NULLIF(\"Delivery Time\", \'\')::DATE AS DELIVERED_DATE, NULLIF(\"Delivery Time\", \'\')::TIMESTAMP AS DELIVERED_TIMESTAMP, category, \"Cost Price\" AS COST, NULLIF(\"Invoice Created\", \'\')::TIMESTAMP AS INVOICE_DATE, \"Tracking Number\" AS AWB, \"Shipping Courier\" AS SHIPPING_COURIER, ROW_NUMBER() OVER (PARTITION BY \"Sale Order Item Code\" ORDER BY NULLIF(UPDATED, \'\') DESC) AS row_num, \"On Hold\" as ON_HOLD FROM snitch_db.maplemonk.Snitch_uc_New_get_sale_orders ) SELECT * FROM ranked_data WHERE row_num = 1; create or replace table snitch_db.maplemonk.warehouse_sla_performance as WITH unicom AS ( SELECT awb, MARKETPLACE, marketplace_mapped, shippingpackagecode, order_id, order_name, SELLING_PRICE, saleorderitemcode, sku, order_status, order_date, order_timestamp, SHIPPING_LAST_UPDATE_TIMESTAMP, shipping_courier, warehouse_name, shipping_status, ON_HOLD, CASE WHEN SALE_ORDER_ITEM_STATUS = \'PICKING_FOR_INVOICING\' THEN shippingpackagestatus ELSE SALE_ORDER_ITEM_STATUS END AS UC_STATUS, dispatched_timestamp AS \"UC_Dispatched\", dispatch_date, delivered_date, item_details, address_line_1, uc_created, CASE WHEN upper(MARKETPLACE) = \'SHOPIFY\' THEN CASE WHEN order_date > \'2024-09-20\' THEN CASE WHEN upper(warehouse_name) = \'SAPL-WH2\' THEN CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 3 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'5 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 3 AND (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'5 hours\' ELSE fulfillment_tat END ELSE CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'18 hours\' ELSE fulfillment_tat END END ELSE CASE WHEN (EXTRACT(HOUR FROM uc_created)) < 16 THEN DATE_TRUNC(\'day\', uc_created::timestamp) + INTERVAL \'18 hours\' WHEN (EXTRACT(HOUR FROM uc_created)) >= 16 THEN DATE_TRUNC(\'day\', DATEADD(DAY, 1, uc_created::timestamp)) + INTERVAL \'18 hours\' ELSE fulfillment_tat END END ELSE fulfillment_tat END AS TAT, category FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 ), forward AS ( SELECT \"Shipping Package Code\", created_timestamp, picking_timestamp, picked_timestamp, packed_timestamp, rts_timestamp, manifested_timestamp, dispatched_timestamp AS dispatched_timestamp1, shipped_timestamp, delivered_timestamp, cancelled_timestamp, \"created&dispatch\", \"pick&dispatch\", \"pack&dispatch\", LATEST_STATUS, LAST_UPDATED FROM snitch_db.maplemonk.forward_timestamps ), clickpost AS ( SELECT awb, \"Order Date\" AS CP_orderplaced, \"Pickup Date\", \"Delivery Date\" AS CP_Delivery, \"Clickpost Unified Status\" as CP_STATUS FROM snitch_db.maplemonk.snitch_clickpost_track_order_dashboard_report ), sr AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_SR ), wh AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_WH ), wh2 AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_WH2 ), emiza AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_SAPL_EMIZA ), marketplace AS ( SELECT \"Order ID\", warehouse FROM snitch_db.maplemonk.GS_MARKET_PLACE_ERROR_ORDERS ), unicom_error AS ( SELECT u.*, CASE WHEN u.marketplace_mapped = \'SHOPIFY\' THEN CASE WHEN u.warehouse_name = \'SAPL_EMIZA\' AND EXISTS (SELECT 1 FROM emiza WHERE emiza.\"Order ID\" = u.order_name AND emiza.warehouse = \'SAPL_EMIZA\') THEN 1 WHEN u.warehouse_name = \'SAPL-WH\' AND EXISTS (SELECT 1 FROM wh WHERE wh.\"Order ID\" = u.order_name AND wh.warehouse = \'SAPL-WH\') THEN 1 WHEN u.warehouse_name = \'SAPL-SR\' AND EXISTS (SELECT 1 FROM sr WHERE sr.\"Order ID\" = u.order_name AND sr.warehouse = \'SAPL-SR\') THEN 1 WHEN u.warehouse_name = \'SAPL-WH2\' AND EXISTS (SELECT 1 FROM wh2 WHERE wh2.\"Order ID\" = u.order_name AND wh2.warehouse = \'SAPL-WH2\') THEN 1 ELSE NULL END WHEN u.marketplace_mapped NOT IN (\'SHOPIFY\', \'OWN_STORE\', \'FRANCHISE_STORE\') THEN CASE WHEN EXISTS (SELECT 1 FROM marketplace WHERE marketplace.\"Order ID\" = u.order_name AND marketplace.warehouse = u.warehouse_name) THEN 1 ELSE NULL END ELSE NULL END AS ERROR FROM unicom u ), main_data AS ( SELECT ue.*, f.created_timestamp, f.picking_timestamp, f.picked_timestamp, f.packed_timestamp, f.rts_timestamp, f.manifested_timestamp, f.dispatched_timestamp1, f.shipped_timestamp, f.delivered_timestamp, f.cancelled_timestamp, f.\"created&dispatch\", f.\"pick&dispatch\", f.\"pack&dispatch\", f.LATEST_STATUS, f.LAST_UPDATED, cp.CP_orderplaced, cp.\"Pickup Date\", cp.CP_Delivery, cp.CP_STATUS FROM unicom_error ue LEFT JOIN forward f ON ue.shippingpackagecode = f.\"Shipping Package Code\" LEFT JOIN clickpost cp ON ue.awb = cp.awb ), over AS ( SELECT don, soic, facwarehouse, overrulestatus FROM snitch_db.maplemonk.gs_overrule ), mast1 AS ( SELECT md.*, ov.* FROM main_data md LEFT JOIN over ov ON md.saleorderitemcode = ov.soic ), new_status AS ( SELECT m1.*, CASE when overrulestatus = \'DISPATCHED\' THEN created_timestamp END AS dispatchedtimestamp2, CASE WHEN UC_STATUS IN (\'UNFULFILLABLE\', \'DISPATCHED\', \'DELIVERED\', \'SHIPPED\', \'RETURN_EXPECTED\', \'CANCELLED\', \'REPLACED\', \'RETURNED\') THEN UC_STATUS ELSE COALESCE(LATEST_STATUS, UC_STATUS) END AS ITEM_STATUS2, COALESCE(dispatchedtimestamp2,COALESCE(dispatched_timestamp1, \"UC_Dispatched\")) AS dispatched_timestamp, coalesce (overrulestatus,item_status2) as ITEM_STATUS, CASE WHEN ITEM_STATUS = \'CANCELLED\' THEN CASE WHEN dispatched_timestamp IS NULL THEN \'CANCELLED\' ELSE CASE WHEN dispatched_timestamp <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END END WHEN TAT > CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', GETDATE()) AND ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\') THEN \'FUTURE DATE-COMPLETED\' WHEN TAT > CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', GETDATE()) AND ITEM_STATUS NOT IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURNED\') THEN \'FUTURE DATE-PENDING\' ELSE CASE WHEN ITEM_STATUS IN (\'DISPATCHED\', \'REPLACED\', \'DELIVERED\', \'SHIPPED\', \'RETURN_EXPECTED\') THEN CASE WHEN dispatched_timestamp <= TAT THEN \'WITHIN SLA\' ELSE \'BREACHED\' END WHEN ITEM_STATUS IN (\'CREATED\', \'MANIFESTED\', \'PICKING\', \'PICKED\', \'PACKED\', \'READY_TO_SHIP\', \'PICKING_FOR_INVOICING\', \'FULFILLABLE\') THEN \'BREACHED - PENDING FOR PROCESS\' WHEN ITEM_STATUS = \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' ELSE \'BREACHED\' END END AS SLA_Status, CASE WHEN marketplace_mapped = \'MYNTRA\' THEN CASE WHEN LOWER(SLA_Status) = \'cancelled\' THEN \'CANCELLED\' WHEN LOWER(SLA_Status) NOT IN (\'cancelled\', \'within sla\', \'breached\', \'future date-completed\') THEN \'PENDING\' ELSE CASE WHEN category IN (\'Accessories\', \'Sunglass\', \'Shorts\', \'Pyjama\', \'Boxer\', \'Co-ords\', \'Jogsuit\', \'Underpants\') AND item_details IS NULL THEN \'CORRECT\' WHEN LOWER(item_details) LIKE \'%mp%\' THEN \'CORRECT\' ELSE \'INCORRECT\' END END ELSE \'OTHER CHANNEL\' END AS Myntra_Tag_Loops, CASE WHEN EXTRACT(HOUR FROM TAT) = 5 THEN \'Night_Shift_TAT\' WHEN EXTRACT(HOUR FROM TAT) = 18 THEN \'Day_Shift_TAT\' ELSE \'MP_SHIFT_TAT\' END AS tat_type , CASE WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 0 THEN \'D0\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 1 THEN \'D1\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 2 THEN \'D2\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 3 THEN \'D3\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 3 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 5 THEN \'D>3\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 5 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 7 THEN \'D>5\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 7 AND TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) <= 9 THEN \'D>7\' WHEN TIMESTAMPDIFF(DAY, TAT, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) > 9 THEN \'D>9\' END AS Ageing, case when dispatched_timestamp IS NOT NULL AND ((\"Pickup Date\" IS NULL) OR (\"Pickup Date\" = \'\')) AND awb IS NOT NULL AND marketplace_mapped = \'SHOPIFY\' AND cp_status not in (\'Cancelled\',\'RTO-Delivered\') THEN \'Handover_Pending\' ELSE \'NA\' END AS handover_status, CASE WHEN dispatched_timestamp IS NOT NULL AND ((\"Pickup Date\" IS NULL) OR (\"Pickup Date\" = \'\')) AND awb IS NOT NULL AND marketplace_mapped = \'SHOPIFY\' THEN CASE WHEN TIMESTAMPDIFF(HOUR, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) < 12 THEN \'<12H\' WHEN TIMESTAMPDIFF(HOUR, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 12 AND 24 THEN \'1D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) = 1 THEN \'2D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 2 AND 5 THEN \'5D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 5 AND 10 THEN \'10D\' WHEN TIMESTAMPDIFF(DAY, dispatched_timestamp, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 10 AND 30 THEN \'30D\' ELSE \'30D+\' END ELSE \'NA\' END as handover_ageing FROM mast1 m1 ) SELECT * FROM new_status WHERE (warehouse_name LIKE \'%SAPL%\' OR warehouse_name IS NULL)",
                    "transaction": true
                }
            ) }}
            with sample_data as (

